function eraseWithDigits(s: string): string {
  let i = 0;
  while (i < s.length) {
    if (s[i] >= "0" && s[i] <= "9") {
      // the character right before the first digit is always a letter
      s = s.slice(0, i - 1) + s.slice(i + 1);
      i--;
    } else i++;
  }
  return s;
}

